/* Shared logic: state, search, phrase cards, page shell. Data comes from data.js (generated by build.py). */
const App = (() => {
  const $ = (s, r = document) => r.querySelector(s);
  const esc = s => String(s).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const shuffle = a => { a = a.slice(); for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; };

  const st = {
    get(k, d) { try { const v = localStorage.getItem("ap:" + k); return v == null ? d : JSON.parse(v); } catch (e) { return d; } },
    set(k, v) { try { localStorage.setItem("ap:" + k, JSON.stringify(v)); } catch (e) { } }
  };

  /* ----- i18n: [arabic, english]; switching reloads the page ----- */
  const L = st.get("lang", "ar") === "en" ? "en" : "ar";
  document.documentElement.lang = L; document.documentElement.dir = L === "en" ? "ltr" : "rtl";
  const D = {
    nav_home: ["الرئيسية", "Home"], nav_browse: ["تصفّح", "Browse"], nav_practice: ["التدريب", "Practice"], nav_saved: ["محفوظاتي", "My Saved"],
    nav_aria: ["التنقل", "Navigation"], theme_aria: ["تبديل الوضع الداكن", "Toggle dark mode"], lang_aria: ["التبديل إلى الإنجليزية", "Switch to Arabic"], lang_btn: ["EN", "ع"],
    foot: ["SaySo · {0} مثلًا في {1} فئة · تُحفظ بياناتك على جهازك فقط", "SaySo · {0} proverbs in {1} categories · Your data stays on your device"],
    speak: ["🔊 نطق", "🔊 Speak"], speak_aria: ["نطق المثل", "Pronounce the proverb"], copy: ["نسخ", "Copy"], fav_add: ["☆ مفضلة", "☆ Favorite"], fav_on: ["⭐ في المفضلة", "⭐ Favorited"],
    learn_add: ["حفظتها", "I know it"], learn_on: ["✓ محفوظة", "✓ Learned"], copied: ["تم نسخ الترجمة", "Translation copied"], copy_fail: ["تعذّر النسخ", "Copy failed"],
    daily_aria: ["مثل اليوم", "Proverb of the day"], proverb: ["المثل", "Proverb"], all: ["الكل", "All"],
    t_home: ["SaySo · تعلّم الإنجليزية من العربية", "SaySo · Learn English through Arabic proverbs"], t_browse: ["تصفّح · SaySo", "Browse · SaySo"], t_practice: ["التدريب · SaySo", "Practice · SaySo"], t_saved: ["محفوظاتي · SaySo", "My Saved · SaySo"],
    h1_home: ["المثل الذي تعرفه بالعربية،<br>ومثله عند الإنجليز", "The proverb you know in Arabic,<br>and its twin in English"],
    lead: ["{0} مثلًا عربيًا مع نظيره الإنجليزي في {1} فئة، مع النطق والاختبارات. قلها بالعربية، وقلها كما يقولها أهل اللغة.", "{0} Arabic proverbs paired with their English equivalents in {1} categories, with pronunciation and quizzes. Say it in Arabic, then say it the English way."],
    ph_search: ["ابحث بالعربية أو الإنجليزية…", "Search in Arabic or English…"], ph_browse: ["ابحث بالعربية أو الإنجليزية… (اضغط /)", "Search in Arabic or English… (press /)"], search_aria: ["بحث", "Search"], btn_search: ["بحث", "Search"],
    h_cats: ["الفئات", "Categories"], h_start: ["ابدأ من هنا", "Start here"],
    f1_t: ["تصفّح SaySo", "Browse SaySo"], f1_p: ["بحث يتجاهل التشكيل بالعربية والإنجليزية، مع نطق ونسخ بضغطة.", "Search in Arabic or English (diacritics ignored), with pronunciation and one-tap copy."],
    f2_t: ["تدريب", "Practice"], f2_p: ["اختبار نظير المثل، بطاقات تعليمية، وتمرين كتابة.", "Equivalent quiz, flashcards, and a typing drill."],
    f3_t: ["محفوظاتي", "My Saved"], f3_p: ["مفضلتك وتقدّمك وسلسلة أيامك، مع إمكانية التصدير.", "Your favorites, progress and daily streak, with export."],
    st_proverbs: ["مثل", "Proverbs"], st_cats: ["فئة", "Categories"], st_learned: ["محفوظة", "Learned"], st_streak: ["يوم متواصل", "Day streak"], n_proverbs: ["{0} مثل", "{0} proverbs"],
    rnd: ["عشوائية", "Random"], hide: ["إخفاء المحفوظة", "Hide learned"], results: ["{0} نتيجة", "{0} results"], no_results: ["لا توجد نتائج، جرّب كلمة أخرى.", "No results. Try another word."], more: ["عرض المزيد", "Show more"], rnd_label: ["مثل عشوائي", "Random proverb"],
    h_practice: ["التدريب", "Practice"], cat_aria: ["الفئة", "Category"], tab_quiz: ["اختبار", "Quiz"], tab_flash: ["بطاقات تعليمية", "Flashcards"], tab_type: ["كتابة", "Typing"],
    q_prog: ["سؤال {0} من {1} · النتيجة {2}", "Question {0} of {1} · Score {2}"], q_text: ["ما نظير المثل بالإنجليزية: «{0}»؟", "What is the English equivalent of: “{0}”?"],
    new_quiz: ["اختبار جديد", "New quiz"], best: ["أفضل نتيجة: {0}", "Best score: {0}"], ok: ["✓ صحيح", "✓ Correct"], wrong: ["✗ خطأ", "✗ Wrong"], ans: ["✗ الإجابة", "✗ Answer"],
    next: ["التالي ←", "Next →"], result: ["النتيجة", "Result"], flash_done: ["أنهيت البطاقات", "You finished the cards"], again: ["من جديد", "Again"],
    f_prog: ["بطاقة {0} من {1} · اضغط على البطاقة لقلبها", "Card {0} of {1} · Tap the card to flip"], knew: ["عرفتها", "Got it"], review: ["أراجعها", "Review"],
    t_prog: ["كتابة {0} من {1} · النتيجة {2}", "Typing {0} of {1} · Score {2}"], t_text: ["اكتب نظير المثل بالإنجليزية: «{0}»", "Type the English equivalent of: “{0}”"], check: ["تحقق", "Check"],
    h_saved: ["محفوظاتي", "My Saved"], chip_fav: ["مفضلة", "Favorites"], chip_learned: ["محفوظة", "Learned"], chip_prog: ["التقدّم", "Progress"], chip_best: ["أفضل اختبار", "Best quiz"], chip_streak: ["يوم متواصل", "Day streak"],
    prog_text: ["{0} من {1} مثل محفوظ", "{0} of {1} proverbs learned"], empty_fav: ["لم تضف مفضلة بعد. اضغط «مفضلة» على أي مثل.", "No favorites yet. Tap “Favorite” on any proverb."], empty_learned: ["لم تحفظ شيئًا بعد. جرّب التدريب.", "Nothing learned yet. Try practice."],
    tab_fav: ["المفضلة", "Favorites"], tab_learned: ["المحفوظة", "Learned"], export: ["تصدير JSON", "Export JSON"], reset: ["تصفير التقدّم", "Reset progress"], reset_confirm: ["تصفير المحفوظات وأفضل نتيجة؟ (المفضلة تبقى)", "Reset learned items and best score? (Favorites are kept)"]
  };
  const t = (k, ...a) => { let s = (D[k] || [k, k])[L === "en" ? 1 : 0]; a.forEach((v, i) => { s = s.split("{" + i + "}").join(v); }); return s; };
  const CAT_EN = { "الصبر والأمل": "Patience & Hope", "الصداقة والناس": "Friends & People", "العمل والاجتهاد": "Work & Effort", "المال والقناعة": "Money & Contentment", "الكلام والصمت": "Speech & Silence", "الأسرة والطبع": "Family & Character", "العدل والجزاء": "Justice & Consequences", "الحكمة والتجارب": "Wisdom & Experience", "العلم والمعرفة": "Knowledge & Learning", "الصحة والبيئة": "Health & Nature", "الإيمان والقدر": "Faith & Destiny" };
  const catName = c => c === "الكل" ? t("all") : (L === "en" ? CAT_EN[c] || c : c);
  function applyI18n() {
    document.querySelectorAll("[data-i18n]").forEach(e => { e.innerHTML = t(e.dataset.i18n); });
    document.querySelectorAll("[data-i18n-ph]").forEach(e => { e.placeholder = t(e.dataset.i18nPh); });
    document.querySelectorAll("[data-i18n-aria]").forEach(e => e.setAttribute("aria-label", t(e.dataset.i18nAria)));
  }

  /* Same normalisation as app.py: ignore tashkeel, alef/yaa/taa-marbuta variants, punctuation */
  const norm = s => String(s).toLowerCase()
    .replace(/[\u064B-\u065F\u0670\u0640]/g, "")
    .replace(/[إأآٱ]/g, "ا").replace(/ى/g, "ي").replace(/ة/g, "ه")
    .replace(/[^\p{L}\p{N}\s']/gu, " ").replace(/\s+/g, " ").trim();

  const P = PHRASES.map((p, i) => ({ ...p, id: i, _a: norm(p.arabic), _e: norm(p.english), _all: norm(p.arabic + " " + p.english) }));
  const cats = [...new Set(P.map(p => p.category))];
  const icons = { "الصبر والأمل": "⏳", "الصداقة والناس": "🤝", "العمل والاجتهاد": "🛠️", "المال والقناعة": "💰", "الكلام والصمت": "🤐", "الأسرة والطبع": "👪", "العدل والجزاء": "⚖️", "الحكمة والتجارب": "💡", "العلم والمعرفة": "📚", "الصحة والبيئة": "🩺", "الإيمان والقدر": "🕌" };

  function search(q, cat = "الكل") {
    let l = cat === "الكل" ? P : P.filter(p => p.category === cat);
    const n = norm(q || "");
    if (!n) return l;
    const toks = n.split(" ");
    return l.map(p => {
      if (!toks.every(t => p._all.includes(t))) return null;
      let s = 0;
      if (p._a === n || p._e === n) s += 100;
      if (p._a.startsWith(n) || p._e.startsWith(n)) s += 40;
      if (p._a.includes(n) || p._e.includes(n)) s += 20;
      return [s, p];
    }).filter(Boolean).sort((a, b) => b[0] - a[0]).map(x => x[1]);
  }

  /* ----- favourites / learned / streak ----- */
  let fav = st.get("favorites", []);
  let learned = new Set(st.get("learned-phrases", []));
  const changed = () => document.dispatchEvent(new Event("app:change"));
  const isFav = a => fav.some(f => f.arabic === a);
  const isLearned = a => learned.has(a);
  const today = () => new Date().toISOString().slice(0, 10);
  const touchDay = () => { const d = st.get("days", []); if (!d.includes(today())) { d.push(today()); st.set("days", d.slice(-400)); } };
  function streak() {
    const d = new Set(st.get("days", [])); let n = 0, t = new Date();
    if (!d.has(t.toISOString().slice(0, 10))) t.setDate(t.getDate() - 1);
    while (d.has(t.toISOString().slice(0, 10))) { n++; t.setDate(t.getDate() - 1); }
    return n;
  }
  const api = {
    toggleFav(p) { fav = isFav(p.arabic) ? fav.filter(f => f.arabic !== p.arabic) : [...fav, { arabic: p.arabic }]; st.set("favorites", fav); api.fav = fav; changed(); },
    setLearned(p, ok) { ok ? learned.add(p.arabic) : learned.delete(p.arabic); st.set("learned-phrases", [...learned]); api.learned = learned; touchDay(); changed(); }
  };

  /* ----- helpers ----- */
  function speak(t) {
    if (!("speechSynthesis" in window)) return;
    const u = new SpeechSynthesisUtterance(t); u.lang = "en-US"; u.rate = .9;
    speechSynthesis.cancel(); speechSynthesis.speak(u);
  }
  let tt;
  function toast(m) {
    let e = $(".toast"); if (!e) { e = document.createElement("div"); e.className = "toast"; e.setAttribute("role", "status"); document.body.append(e); }
    e.textContent = m; e.classList.add("show"); clearTimeout(tt); tt = setTimeout(() => e.classList.remove("show"), 1600);
  }
  const hl = (t, q) => {
    const s = esc(t); const k = (q || "").trim(); if (!k) return s;
    try { return s.replace(new RegExp(esc(k).replace(/[.*+?^${}()|[\]\\]/g, "\\$&"), "gi"), m => `<mark>${m}</mark>`); } catch (e) { return s; }
  };
  const actions = p => `<div class="acts">
    <button data-act="speak" data-id="${p.id}" aria-label="${t("speak_aria")}">${t("speak")}</button>
    <button data-act="copy" data-id="${p.id}">${t("copy")}</button>
    <button data-act="fav" data-id="${p.id}" aria-pressed="${isFav(p.arabic)}">${isFav(p.arabic) ? t("fav_on") : t("fav_add")}</button>
    <button data-act="learn" data-id="${p.id}" aria-pressed="${isLearned(p.arabic)}">${isLearned(p.arabic) ? t("learn_on") : t("learn_add")}</button></div>`;

  function card(p, q) {
    return `<article class="card entry${isLearned(p.arabic) ? " learned" : ""}">
      <span class="tag">${icons[p.category] || "📌"} ${esc(catName(p.category))}</span>
      <p class="ar" lang="ar" dir="rtl">${hl(p.arabic, q)}</p>
      <p class="en" lang="en" dir="ltr">${hl(p.english, q)}</p>
      ${actions(p)}</article>`;
  }
  function spread(p) {
    return `<section class="spread" aria-label="${t("daily_aria")}">
      <div><span class="label">${t("proverb")} · ${esc(catName(p.category))}</span><p class="ar" lang="ar" dir="rtl">${esc(p.arabic)}</p></div>
      <div class="side-en"><span class="label" dir="ltr">The English equivalent</span><p class="en" lang="en" dir="ltr">${esc(p.english)}</p>${actions(p)}</div></section>`;
  }

  document.addEventListener("click", e => {
    const b = e.target.closest("[data-act]"); if (!b) return;
    const p = P[+b.dataset.id], a = b.dataset.act;
    if (a === "speak") speak(p.english);
    else if (a === "copy") (navigator.clipboard ? navigator.clipboard.writeText(p.english) : Promise.reject()).then(() => toast(t("copied")), () => toast(t("copy_fail")));
    else if (a === "fav") api.toggleFav(p);
    else if (a === "learn") api.setLearned(p, !isLearned(p.arabic));
  });

  /* ----- page shell: header, footer, theme, service worker ----- */
  function applyTheme(t) { if (t) document.documentElement.dataset.theme = t; else delete document.documentElement.dataset.theme; }
  applyTheme(st.get("theme", null));
  function shell() {
    const page = location.pathname.split("/").pop() || "index.html";
    const links = [["index.html", t("nav_home")], ["phrases.html", t("nav_browse")], ["practice.html", t("nav_practice")], ["favorites.html", t("nav_saved")]];
    document.body.insertAdjacentHTML("afterbegin", `<header class="top"><div class="top-in">
      <a class="brand" href="index.html"><i aria-hidden="true">S</i><span class="wm" dir="ltr">Say<b>So</b></span></a>
      <nav class="nav" aria-label="${t("nav_aria")}">${links.map(l => `<a href="${l[0]}"${page === l[0] || (page === "" && l[0] === "index.html") ? ' aria-current="page"' : ""}>${l[1]}</a>`).join("")}</nav>
      <button class="icon-btn lang-btn" id="lang" aria-label="${t("lang_aria")}">${t("lang_btn")}</button><button class="icon-btn" id="theme" aria-label="${t("theme_aria")}">◐</button></div></header>`);
    document.body.insertAdjacentHTML("beforeend", `<footer class="foot">SaySo · ${t("foot", P.length, cats.length)}</footer>`);
    $("#theme").onclick = () => {
      const dark = document.documentElement.dataset.theme === "dark" || (!document.documentElement.dataset.theme && matchMedia("(prefers-color-scheme:dark)").matches);
      const t = dark ? "light" : "dark"; st.set("theme", t); applyTheme(t);
    };
    $("#lang").onclick = () => { st.set("lang", L === "en" ? "ar" : "en"); location.reload(); };
    applyI18n();
    if ("serviceWorker" in navigator && location.protocol.startsWith("http")) navigator.serviceWorker.register("sw.js").catch(() => { });
  }
  document.readyState === "loading" ? document.addEventListener("DOMContentLoaded", shell) : shell();

  return Object.assign(api, { t, L, catName, P, cats, icons, $, esc, shuffle, st, norm, search, card, spread, speak, toast, isFav, isLearned, streak, fav, learned });
})();
